// The server tree the desktop shell runs: a verbatim copy of the game checkout's `server/` and `shared/`.
//
// Why a second copy of the server code, next to the payload (`build/client/www`):
//
//   * The payload's `server/` is *page-side*. Its `server/data.js` is generated by us (it fetches `/data/*.json`
//     and takes the sim's data from the page), because the in-page engine imports it as `../data.js`. Upstream's
//     own `server/data.js` reads the data directory and exports the paths (`ROOT`, `DATA_DIR`) that the plugin
//     layer defaults to — two incompatible roles for one path. Shipping the node tree separately keeps each tree
//     self-consistent instead of making one file serve both.
//   * 0.3.0 serves plugins, content sets and visual sets from `server/http/static.js`, driven by
//     `server/plugins/registry.js`. Those modules are Node-only (fs / path / crypto), so the *page* can never load
//     them — but the desktop shell's main process can, which is how a packaged client serves `/plugins/`, `/p/`,
//     `/vs/` and `/cs/` with upstream's own semantics (hashed URLs, ETags, ranges, caching) instead of a
//     reimplementation that would drift.
//
// It is shipped as `resources/srv` and never served: the static handler's mounts point at the payload, so nothing
// under this tree is reachable over HTTP. `tools/server-tree.mjs` copies it; docs/PACKAGING.md §17 explains the
// split, and §18 how a player adds plugins to it.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CLIENT_ROOT } from './package-client.mjs';
import { CONTRACT_FILE, DATA_SHIM_JS, SIM_PRIVATE, findGameRoot, readGameContract } from './game-contract.mjs';

/** Where the tree is staged (electron-builder copies it to `resources/srv`). */
export const SRV_DIR = path.join(CLIENT_ROOT, 'build', 'client', 'srv');
/** Top-level game-repo directories the node layer lives in (relative imports inside them resolve as upstream). */
export const SRV_MOUNTS = Object.freeze(['server', 'shared']);

/** Every file under `dir`, as `/`-separated paths. */
function walk(dir, rel = '') {
  const out = [];
  for (const e of fs.readdirSync(path.join(dir, rel), { withFileTypes: true })) {
    const child = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) out.push(...walk(dir, child));
    else if (e.isFile()) out.push(child);
  }
  return out;
}

/**
 * Stage `server/` + `shared/` from a checkout into `out`.
 *
 * Verbatim by design: these files are upstream's, and their relative imports (`../plugins/registry.js`,
 * `../../shared/…`, `./data.js`) only resolve when the layout is the checkout's. Nothing is rewritten — the one
 * thing to check is that the copy still declares the same contract the payload was built from, which
 * {@link assertServerTreeContract} does.
 *
 * @param {{ gameRoot: string, out?: string, log?: (...a: any[]) => void }} o
 * @returns {{ out: string, files: number, bytes: number, mounts: string[] }}
 */
export function stageServerTree(o) {
  const log = o.log ?? (() => {});
  const out = path.resolve(o.out ?? SRV_DIR);
  fs.rmSync(out, { recursive: true, force: true });
  let files = 0;
  let bytes = 0;
  for (const mount of SRV_MOUNTS) {
    const src = path.join(o.gameRoot, mount);
    if (!fs.existsSync(src)) throw new Error(`${o.gameRoot}/${mount} 不存在 —— 服务端代码树不完整，桌面壳无法加载插件层`);
    for (const rel of walk(src)) {
      const from = path.join(src, rel);
      const to = path.join(out, mount, rel);
      fs.mkdirSync(path.dirname(to), { recursive: true });
      fs.copyFileSync(from, to);
      files++;
      bytes += fs.statSync(to).size;
    }
  }
  log(`server-tree: ${out.split(path.sep).join('/')} —— ${files} 个文件, ${(bytes / 1048576).toFixed(1)} MB（原样复制 ${SRV_MOUNTS.join(' + ')}）`);
  return { out, files, bytes, mounts: [...SRV_MOUNTS] };
}

/**
 * The node tree and the payload must agree on the contract (DATA_SHIM_JS / SIM_PRIVATE), or the shell would serve
 * `/data.js` from one build while computing content identities from another — a plugin's content hash would then
 * never match what the page verifies. Both copies come from the same checkout, and `verifyGameContract` has already
 * pinned the checkout to the constants in tools/game-contract.mjs, so this compares the staged copy against those.
 *
 * @param {string} srvDir
 * @returns {true}
 */
export function assertServerTreeContract(srvDir) {
  const file = path.join(srvDir, CONTRACT_FILE);
  if (!fs.existsSync(file)) throw new Error(`服务端代码树里没有 ${CONTRACT_FILE} —— 重新 stage`);
  const node = readGameContract(fs.readFileSync(file, 'utf8'));
  if (node.shim !== DATA_SHIM_JS) {
    throw new Error(`${CONTRACT_FILE} 里的 DATA_SHIM_JS 与 payload 的不一致 —— 服务端代码树和 payload 不是同一次构建（重新打包）`);
  }
  const a = [...node.simPrivate].sort().join(',');
  const b = [...SIM_PRIVATE].sort().join(',');
  if (a !== b) throw new Error(`${CONTRACT_FILE} 里的 SIM_PRIVATE（${a}）与 payload 的不一致（${b}）`);
  return true;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const argv = process.argv.slice(2);
  const opt = (name) => {
    const i = argv.indexOf(name);
    return i === -1 ? undefined : argv[i + 1];
  };
  const gameRoot = findGameRoot({ clientRoot: CLIENT_ROOT, cli: opt('--game') });
  const staged = stageServerTree({ gameRoot, out: opt('--out'), log: console.log });
  console.log(`server-tree: → ${staged.out.split(path.sep).join('/')}`);
}
